#include <iostream>
#include <string>
#include <sstream>

int main() {
    std::string input = "Input test 123 4.7 A";
    std::istringstream inputString(input);

    std::string string1;
    std::string string2;
    int integer = 0;
    double double1 = 0.0;
    char character = '\0';

    inputString >> string1 >> string2 >> integer >> double1 >> character;

    std::cout << "The following items were extracted\n"
              << "from the istringstream object:\n"
              << "string: " << string1 << "\n"
              << "string: " << string2 << "\n"
              << "   int: " << integer << "\n"
              << "double: " << double1 << "\n"
              << "  char: " << character << "\n";

    // Attempt to read from empty stream
    long value = 0;
    inputString >> value;

    // Test stream results
    if (inputString.good()) {
        std::cout << "\nlong value is: " << value << std::endl;
    } else {
        std::cout << "\ninputString is empty" << std::endl;
    }

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    // 1. to_string examples
    int intVal = 100;
    double dblVal = 123.45;
    std::string sInt = std::to_string(intVal);
    std::string sDbl = std::to_string(dblVal);
    std::cout << "sInt: " << sInt << "\nsDbl: " << sDbl << "\n";

    // 2. Converting string with unconverted characters
    std::string strInt = "100hello";
    int convertedInt = std::stoi(strInt);
    std::cout << "convertedInt: " << convertedInt << "\n";

    // 3. Using custom base and unparsed index tracking
    std::size_t index = 0;
    int binaryParsed = std::stoi(strInt, &index, 2);
    std::cout << "binaryParsed: " << binaryParsed 
              << ", first unparsed character: '" << strInt[index] 
              << "' at index " << index << "\n";

    // 4. Floating-point conversion with unparsed tracking
    std::string strDouble = "123.45hello";
    std::size_t dblIndex = 0;
    double convertedDouble = std::stod(strDouble, &dblIndex);
    std::cout << "convertedDouble: " << convertedDouble 
              << ", stopped at index " << dblIndex << "\n";

    // 5. Exception handling: invalid_argument & out_of_range
    try {
        int bad = std::stoi("xyz123");
        std::cout << bad << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cout << "Caught invalid_argument for invalid prefix\n";
    }

    try {
        int overflow = std::stoi("99999999999999999999");
        std::cout << overflow << std::endl;
    } catch (const std::out_of_range& e) {
        std::cout << "Caught out_of_range for overflow\n";
    }

    return 0;
}
